  app.post('/dashboard/:guildId/roles/add',requireLogin,requireGuildAccess,checkCsrf,async(req,res)=>{const [cfg,site]=await Promise.all([store.getConfig(req.params.guildId),store.getGlobalConfig()]);if(!featureAllowed(site,cfg,'rolePanel'))return res.status(403).send('Self Roles غير متاحة لهذه الخطة.');const limit=maxFor(req,cfg,site,'selfRoles');if(cfg.rolePanel.items.length>=limit)return res.status(403).send(`وصلت للحد المسموح (${limit}).`);const role=req.bundle.roles.find(r=>r.id===String(req.body.roleId));if(!role)return res.status(400).send('Role invalid');if(!cfg.rolePanel.items.some(p=>p.roleId===role.id))cfg.rolePanel.items.push({roleId:role.id,label:String(req.body.label||role.name).slice(0,80),emoji:String(req.body.emoji||'🔔').slice(0,32)});await store.saveConfig(req.params.guildId,cfg);res.redirect(`/dashboard/${req.params.guildId}`);});
  app.post('/dashboard/:guildId/roles/update',requireLogin,requireGuildAccess,checkCsrf,async(req,res)=>{const [cfg,site]=await Promise.all([store.getConfig(req.params.guildId),store.getGlobalConfig()]);if(!featureAllowed(site,cfg,'rolePanel'))return res.status(403).send('Self Roles غير متاحة لهذه الخطة.');const p=cfg.rolePanel.items.find(x=>x.roleId===String(req.body.roleId));if(!p)return res.status(404).send('الرتبة غير موجودة.');p.label=String(req.body.label||p.label||'Role').slice(0,80);p.emoji=String(req.body.emoji||p.emoji||'🔔').slice(0,32);await store.saveConfig(req.params.guildId,cfg);res.redirect(`/dashboard/${req.params.guildId}`);});
  app.post('/dashboard/:guildId/roles/delete',requireLogin,requireGuildAccess,checkCsrf,async(req,res)=>{const cfg=await store.getConfig(req.params.guildId);cfg.rolePanel.items=cfg.rolePanel.items.filter(p=>p.roleId!==String(req.body.roleId));await store.saveConfig(req.params.guildId,cfg);res.redirect(`/dashboard/${req.params.guildId}`);});
  app.post('/dashboard/:guildId/tickets/type/add',requireLogin,requireGuildAccess,checkCsrf,async(req,res)=>{const [cfg,site]=await Promise.all([store.getConfig(req.params.guildId),store.getGlobalConfig()]);if(!featureAllowed(site,cfg,'tickets'))return res.status(403).send('Tickets غير متاحة لهذه الخطة.');const limit=maxFor(req,cfg,site,'ticketTypes');if(cfg.tickets.types.length>=limit)return res.status(403).send(`وصلت لحد أنواع التذاكر (${limit}).`);let id=slug(req.body.label)||`type-${Date.now().toString(36)}`;while(cfg.tickets.types.some(x=>x.id===id))id=`${id}-${Math.floor(Math.random()*99)}`;cfg.tickets.types.push({id,label:String(req.body.label||'دعم').slice(0,80),emoji:String(req.body.emoji||'🎫').slice(0,32),description:String(req.body.description||'').slice(0,300),supportRoleIds:arr(req.body.typeSupportRoleIds).slice(0,maxFor(req,cfg,site,'ticketSupportRoles'))});await store.saveConfig(req.params.guildId,cfg);res.redirect(`/dashboard/${req.params.guildId}`);});
  app.post('/dashboard/:guildId/tickets/type/update',requireLogin,requireGuildAccess,checkCsrf,async(req,res)=>{const [cfg,site]=await Promise.all([store.getConfig(req.params.guildId),store.getGlobalConfig()]);if(!featureAllowed(site,cfg,'tickets'))return res.status(403).send('Tickets غير متاحة لهذه الخطة.');const t=cfg.tickets.types.find(x=>x.id===String(req.body.typeId));if(!t)return res.status(404).send('نوع التذكرة غير موجود.');t.label=String(req.body.label||t.label||'دعم').slice(0,80);t.emoji=String(req.body.emoji||t.emoji||'🎫').slice(0,32);t.description=String(req.body.description||'').slice(0,300);t.supportRoleIds=arr(req.body.typeSupportRoleIds).slice(0,maxFor(req,cfg,site,'ticketSupportRoles'));await store.saveConfig(req.params.guildId,cfg);res.redirect(`/dashboard/${req.params.guildId}`);});
  app.post('/dashboard/:guildId/tickets/type/delete',requireLogin,requireGuildAccess,checkCsrf,async(req,res)=>{const cfg=await store.getConfig(req.params.guildId);cfg.tickets.types=cfg.tickets.types.filter(x=>x.id!==String(req.body.typeId));if(!cfg.tickets.types.length)cfg.tickets.types=[{id:'general',label:'دعم عام',emoji:'🎫',description:'تذكرة دعم عامة',supportRoleIds:[]}];await store.saveConfig(req.params.guildId,cfg);res.redirect(`/dashboard/${req.params.guildId}`);});
